days.exampleCode:
import time
import json

def get_task():
    return {"task": "summarize", "content": "Python is great"}

def mock_ai_process(data):
    print("正在调用 AI...")
    time.sleep(1)
    return f"摘要: {data['content']} (Processed)"

def save_log(result):
    with open("ai_log.txt", "a", encoding="utf-8") as f:
        f.write(result + "\n")

# 主流程
def main():
    try:
        task = get_task()
        result = mock_ai_process(task)
        save_log(result)
        print("任务完成！")
    except Exception as e:
        print(f"任务出错: {e}")

if __name__ == "__main__":
    main()

